CREATE TABLE users (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
 email VARCHAR(254) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL UNIQUE,
 name VARCHAR(120) NOT NULL,
 password_hash VARCHAR(255) NOT NULL,
 active BOOLEAN NOT NULL DEFAULT TRUE,
 totp_secret TEXT NULL, totp_pending TEXT NULL, totp_last_step BIGINT NOT NULL DEFAULT -1,
 version BIGINT UNSIGNED NOT NULL DEFAULT 1,
 created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE roles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, version BIGINT UNSIGNED NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE permissions (name VARCHAR(100) CHARACTER SET ascii PRIMARY KEY) ENGINE=InnoDB;
CREATE TABLE role_permissions (role_id BIGINT UNSIGNED NOT NULL, permission VARCHAR(100) CHARACTER SET ascii NOT NULL, scope VARCHAR(12) NOT NULL, PRIMARY KEY(role_id,permission), FOREIGN KEY(role_id) REFERENCES roles(id), FOREIGN KEY(permission) REFERENCES permissions(name)) ENGINE=InnoDB;
CREATE TABLE user_roles (user_id BIGINT UNSIGNED NOT NULL, role_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(role_id) REFERENCES roles(id)) ENGINE=InnoDB;
CREATE TABLE teams (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, version BIGINT UNSIGNED NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE team_members (team_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(team_id,user_id), FOREIGN KEY(team_id) REFERENCES teams(id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE sessions (
 token_hash CHAR(64) CHARACTER SET ascii PRIMARY KEY,
 csrf_hash CHAR(64) CHARACTER SET ascii NOT NULL,
 user_id BIGINT UNSIGNED NULL, mfa_complete BOOLEAN NOT NULL DEFAULT FALSE,
 created_at DATETIME(6) NOT NULL, last_activity DATETIME(6) NOT NULL, expires_at DATETIME(6) NOT NULL, reauthenticated_at DATETIME(6) NULL,
 FOREIGN KEY(user_id) REFERENCES users(id), INDEX sessions_user(user_id), INDEX sessions_expiry(expires_at)
) ENGINE=InnoDB;
CREATE TABLE recovery_codes (user_id BIGINT UNSIGNED NOT NULL, code_hash CHAR(64) CHARACTER SET ascii NOT NULL, PRIMARY KEY(user_id,code_hash), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE identity_tokens (token_hash CHAR(64) CHARACTER SET ascii PRIMARY KEY, kind VARCHAR(12) NOT NULL, email VARCHAR(254) CHARACTER SET ascii NOT NULL, user_id BIGINT UNSIGNED NULL, created_by BIGINT UNSIGNED NOT NULL, expires_at DATETIME(6) NOT NULL, consumed_at DATETIME(6) NULL, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE service_identities (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, token_hash CHAR(64) CHARACTER SET ascii NOT NULL UNIQUE, user_id BIGINT UNSIGNED NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, scopes JSON NOT NULL, expires_at DATETIME(6) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE settings (name VARCHAR(80) CHARACTER SET ascii PRIMARY KEY, value JSON NOT NULL, secret TEXT NULL, version BIGINT UNSIGNED NOT NULL DEFAULT 1, updated_at DATETIME(6) NOT NULL) ENGINE=InnoDB;
CREATE TABLE audit_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_type VARCHAR(12) NOT NULL, actor_id VARCHAR(40) NOT NULL, requested_by BIGINT UNSIGNED NULL, action VARCHAR(100) NOT NULL, entity_type VARCHAR(60) NOT NULL, entity_id VARCHAR(80) NOT NULL, source VARCHAR(12) NOT NULL, result VARCHAR(20) NOT NULL, request_id VARCHAR(64) NOT NULL, correlation_id VARCHAR(64) NOT NULL, details JSON NOT NULL, created_at DATETIME(6) NOT NULL, INDEX audit_created(created_at,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE idempotency_records (actor_key VARCHAR(80) CHARACTER SET ascii NOT NULL, operation VARCHAR(100) CHARACTER SET ascii NOT NULL, request_key VARCHAR(100) CHARACTER SET ascii NOT NULL, request_hash CHAR(64) CHARACTER SET ascii NOT NULL, response JSON NOT NULL, created_at DATETIME(6) NOT NULL, PRIMARY KEY(actor_key,operation,request_key)) ENGINE=InnoDB;
CREATE TABLE outbox_events (id CHAR(32) CHARACTER SET ascii PRIMARY KEY, kind VARCHAR(80) CHARACTER SET ascii NOT NULL, payload JSON NOT NULL, user_id BIGINT UNSIGNED NOT NULL, permission VARCHAR(100) NOT NULL, correlation_id VARCHAR(64) NOT NULL, created_at DATETIME(6) NOT NULL, published_at DATETIME(6) NULL, FOREIGN KEY(user_id) REFERENCES users(id), INDEX outbox_pending(published_at,created_at)) ENGINE=InnoDB;
CREATE TABLE jobs (id CHAR(32) CHARACTER SET ascii PRIMARY KEY, kind VARCHAR(80) CHARACTER SET ascii NOT NULL, payload JSON NOT NULL, user_id BIGINT UNSIGNED NOT NULL, permission VARCHAR(100) NOT NULL, correlation_id VARCHAR(64) NOT NULL, status VARCHAR(20) NOT NULL, attempts INT NOT NULL DEFAULT 0, available_at DATETIME(6) NOT NULL, lease_token CHAR(32) CHARACTER SET ascii NULL, lease_until DATETIME(6) NULL, last_error VARCHAR(80) NULL, created_at DATETIME(6) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id), INDEX jobs_pending(status,available_at), INDEX jobs_lease(status,lease_until)) ENGINE=InnoDB;
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, message VARCHAR(500) NOT NULL, read_at DATETIME(6) NULL, created_at DATETIME(6) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id), INDEX notification_user(user_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE documents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, owner_id BIGINT UNSIGNED NOT NULL, team_id BIGINT UNSIGNED NULL, entity_type VARCHAR(60) NULL, entity_id VARCHAR(80) NULL, current_version INT NOT NULL DEFAULT 1, version BIGINT UNSIGNED NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, FOREIGN KEY(owner_id) REFERENCES users(id), FOREIGN KEY(team_id) REFERENCES teams(id)) ENGINE=InnoDB;
CREATE TABLE document_versions (document_id BIGINT UNSIGNED NOT NULL, number INT NOT NULL, object_key VARCHAR(200) NOT NULL UNIQUE, filename VARCHAR(180) NOT NULL, media_type VARCHAR(80) NOT NULL, size_bytes BIGINT NOT NULL, checksum CHAR(64) NOT NULL, status VARCHAR(20) NOT NULL, scan_reference VARCHAR(200) NULL, created_at DATETIME(6) NOT NULL, PRIMARY KEY(document_id,number), FOREIGN KEY(document_id) REFERENCES documents(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE email_messages (id CHAR(32) CHARACTER SET ascii PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, recipient VARCHAR(254) NOT NULL, subject VARCHAR(160) NOT NULL, body TEXT NOT NULL, status VARCHAR(20) NOT NULL, message_id VARCHAR(100) NOT NULL UNIQUE, error_code VARCHAR(80) NULL, updated_at DATETIME(6) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE auth_limits (bucket CHAR(64) CHARACTER SET ascii PRIMARY KEY, attempts INT NOT NULL, window_start DATETIME(6) NOT NULL) ENGINE=InnoDB;
CREATE TABLE bootstrap_guard (id INT PRIMARY KEY) ENGINE=InnoDB;
CREATE TABLE user_preferences (user_id BIGINT UNSIGNED PRIMARY KEY, value JSON NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
